from __future__ import annotations

import json
import logging
import os
import shutil
import sys
import tempfile
from pathlib import Path

from axelera.runtime import op
from axelera.runtime import Postamble

# Compiler and third-party chatter is INFO/DEBUG, which the stdlib default
# (WARNING) already hides. AXZOO_VERBOSE=1 turns the full stream back on.
if os.environ.get('AXZOO_VERBOSE') == '1':
    logging.basicConfig(level=logging.DEBUG, format='%(levelname)s: %(message)s')


# shared/ holds what every recipe does the same way: the command line, the
# weight fetch, the accuracy legs. It ships beside this file in a fork, and one
# level up in the SDK's model_recipes/ tree.
_HERE = Path(__file__).resolve().parent
sys.path[:0] = [str(p) for p in (_HERE, _HERE.parent) if (p / 'shared' / '__init__.py').is_file()]
try:
    import shared  # noqa: E402
except ModuleNotFoundError:
    raise SystemExit(
        f'{Path(__file__).name} reads its command line, its weight fetch and its accuracy '
        f'legs from a shared/ directory beside it. Copy that directory here from the SDK\'s '
        f'model_recipes/, or run `axzoo fork <model> --script`, which writes the recipe and '
        f'the directory together.'
    ) from None
shared.check_beside(__file__)

# === Inputs resolved from BuildConfig ===
INPUT_SIZE = [1, 3, 640, 640]
NUM_CAL = int(os.environ.get('AXZOO_NUM_CAL', 200))
MODEL_NAME = 'yolov5l-coco'
# `axzoo build` sets AXZOO_OUTPUT; a standalone run writes here.
OUTPUT_PATH = Path(os.environ.get('AXZOO_OUTPUT', 'build/yolov5l-coco.axm'))
MODEL_METADATA = json.loads(os.environ.get('AXZOO_METADATA_JSON', '{}'))
# Downloads land here and are reused across runs.
CACHE_DIR = Path(os.environ.get('AXZOO_HOME', Path.home() / '.cache' / 'axelera' / 'zoo'))
ASSET_HOST = os.environ.get('AXZOO_ENDPOINT', 'https://media.axelera.ai/artifacts/model_cards')

# === Weight-format sources ===
# Each declared source is embedded; AXZOO_WEIGHT_FORMAT picks one at build
# time (default: DEFAULT_WEIGHT_FORMAT).
DEFAULT_WEIGHT_FORMAT = 'onnx'
SOURCES = {
    'onnx': {
        'kind': 'remote',
        'weight_url': 'weights/yolo/object_detection/yolov5l-v7.onnx',
        'weight_path': 'yolov5l-v7.onnx',
        'md5': '2aacc2093df437e37b5eac28d18a5442',
    }
}
WEIGHT_FORMAT = os.environ.get('AXZOO_WEIGHT_FORMAT') or DEFAULT_WEIGHT_FORMAT
if WEIGHT_FORMAT not in SOURCES:
    _avail = ', '.join(sorted(SOURCES))
    raise SystemExit(
        f'AXZOO_WEIGHT_FORMAT={WEIGHT_FORMAT!r} is not an embedded source for this '
        f'build; choose one of: {_avail}.'
    )
_ACTIVE_SOURCE = SOURCES[WEIGHT_FORMAT]

# === Preprocess ===
# Must match the runtime pipeline's preprocess exactly: calibration runs
# through the same ops the deployed model sees.
preprocess = op.seq(
    op.color_convert(dst='RGB'),
    op.letterbox(width=640, height=640),
    op.to_tensor(),
)

# The fused decode kernel the build places on this recipe's op.load.
POSTAMBLE = Postamble(
    fused_kernel='AnchoredYoloPostamble',
    anchors=[
        [10.0, 13.0, 16.0, 30.0, 33.0, 23.0],
        [30.0, 61.0, 62.0, 45.0, 59.0, 119.0],
        [116.0, 90.0, 156.0, 198.0, 373.0, 326.0],
    ],
    num_classes=80,
)


# === Pipeline (production, end-to-end) ===
# The exact pipeline this model runs: preprocess -> the compiled .axm -> postprocess.
def build_pipeline(axm_path):
    return op.seq(
        preprocess,
        op.load(str(axm_path), using_postamble=POSTAMBLE),
        op.decode_detections(algo='yolov5', num_classes=80),
        op.nms(),
        op.to_image_space(),
        op.ax_detection(class_id_type=op.CocoClasses),
    )


# === Pipeline (accuracy) ===
# What --eval scores. Same preprocess and same model as above; the tail differs
# because presenting a result and scoring one are different jobs. A detector
# presents named classes and scores integer ids at a low confidence threshold,
# so a metric sees every prediction the evaluator should rank.
def build_eval_pipeline(model_op):
    return op.seq(
        preprocess,
        model_op,
        op.decode_detections(
            algo='yolov5', num_classes=80, confidence_threshold=0.001, use_multi_label=True
        ),
        op.nms(iou_threshold=0.65),
        op.to_image_space(),
        op.ax_detection(),
    )


# === Calibration source ===
# Quantization needs ~200 images that look like what the model will see in
# production. CALIBRATION_DIR wins when set, so no download happens.
CALIBRATION_URL = 'https://media.axelera.ai/artifacts/data/coco/coco2017_repr416.zip'
CALIBRATION_MD5 = 'a923038acd372907e8b4b811e6c069bc'
CALIBRATION_DIR = ''

